7	template <typename T>
8	class FArray1D {
9	
10	  private:
11	    bool ownsData;
12	    int start_i;
13	
14	  public:
15	    size_t ni;
16	    T* data;
17	
18	    // Constructor to allocate memory
19	    FArray1D(size_t ni, int start_i=1)
20	        : ni(ni), start_i(start_i), data(new T[ni]), ownsData(true) {}
21	
22	    // Constructor to use existing Fortran array
23	    FArray1D(T* fortranArray, size_t ni, int start_i=1)
24	        : ni(ni), start_i(start_i), data(fortranArray), ownsData(false) {}
25	
26	    // Constructor using an initializer list
27	    FArray1D(std::initializer_list<T> values, size_t ni, int start_i = 1)
28	        : ni(ni), start_i(start_i), data(new T[ni]), ownsData(true) {
29	        size_t idx = 0;
30	        for (T value : values) {
31	            if (idx < ni) {
32	                data[idx++] = value;
33	            }
34	        }
35	    }
36	
37	    // Destructor to free memory
38	    ~FArray1D() {
39	        if (data != nullptr && ownsData) {
40	            delete[] data;
41	        }
42	    }
43	
44	    // Access operator
45	    T& operator()(size_t i) {
46	        return data[i-start_i];
47	    }
48	
49	    // Const access operator
50	    const T& operator()(size_t i) const {
51	        return data[i-start_i];
52	    }
53	
54	    // Method to attach an existing Fortran array
55	    void attach(T* fortranArray) {
56	        data = fortranArray;
57	        ownsData = false;
58	    }
59	
60	    void fill(const T& value) {
61	        for (size_t i=start_i; i <ni+start_i; i++) {
62	            *this(i) = value;
63	        }
64	    }
65	
66	};
