122	class FArray3D {
123	
124	  private:
125	    bool ownsData;
126	    int start_i, start_j, start_k;
127	
128	  public:
129	    size_t ni, nj, nk;
130	    T* data;
131	
132	    // Constructor to allocate memory
133	    FArray3D(size_t ni, size_t nj, size_t nk, int start_i=1, int start_j=1, int start_k=1)
134	        : ni(ni), nj(nj), nk(nk), start_i(start_i), start_j(start_j), start_k(start_k), data(new T[ni * nj * nk]), ownsData(true) {}
135	
136	    // Constructor to use existing Fortran array
137	    FArray3D(T* fortranArray, size_t ni, size_t nj, size_t nk, int start_i=1, int start_j=1, int start_k=1)
138	        : ni(ni), nj(nj), nk(nk), start_i(start_i), start_j(start_j), start_k(start_k), data(fortranArray), ownsData(false) {}
139	
140	    // Destructor to free memory
141	    ~FArray3D() {
142	        if (data != nullptr && ownsData) {
143	            delete[] data;
144	        }
145	    }
146	
147	    // Access operator
148	    T& operator()(size_t i, size_t j, size_t k) {
149	        return data[i-start_i + ni*(j-start_j+nj*(k-start_k))];
150	    }
151	
152	    // Const access operator
153	    const T& operator()(size_t i, size_t j, size_t k) const {
154	        return data[i-start_i + ni*(j-start_j+nj*(k-start_k))];
155	    }
156	
157	    // Method to attach an existing Fortran array
158	    void attach(T* fortranArray) {
159	        data = fortranArray;
160	        ownsData = false;
161	    }
162	
163	    // Fill method for 3D array (reverse order: k, j, i)
164	    void fill(const T& value) {
165	        for (size_t k=start_k; k<nk+start_k; k++) {
166	            for (size_t j=start_j; j<nj+start_j; j++) {
167	                for (size_t i=start_i; i<ni+start_i; i++) {
168	                    (*this)(i, j, k) = value;
169	                }
170	            }
171	        }
172	    }
173	};
