python3 << 'EOF'
import re

# Read the fortran source
with open('software/mcfm/src/Mods/ppwp2j_mod.f90') as f:
    content = f.read()

# Extract the data
start = content.find('reshape((/')
shape_start = content.rfind('(/ 9,9,9,9 /)')
data_str = content[start+10:shape_start]
data_str = data_str.replace('&', '').replace('\n', ' ')
data_str = data_str.rstrip().rstrip(',').rstrip().rstrip('/').rstrip().rstrip(')')
numbers = [int(m.group()) for m in re.finditer(r'-?\d+', data_str)]
assert len(numbers) == 6561

# Generate C++ array with 27 values per line (matching the Fortran layout)
lines = []
for i in range(0, len(numbers), 27):
    chunk = numbers[i:i+27]
    lines.append('        ' + ', '.join(str(n) for n in chunk))

array_data = ',\n'.join(lines)

# Write the header file
header_content = """#ifndef PPWP2J_MOD
#define PPWP2J_MOD

#include <FArray.hpp>
#include <ppmax_mod.hpp>

namespace ppwp2j_mod {
    using namespace ppmax_mod;
    extern FArray4D<int> pp;
}

#endif
"""

# Write the cpp file
cpp_content = f"""#include <ppwp2j_mod.hpp>
#include <ppmax_mod.hpp>
#include <cstring>

namespace ppwp2j_mod {{
    using namespace ppmax_mod;

    FArray4D<int> pp(9, 9, 9, 9, -4, -4, -4, -4);

    namespace {{
        static const int pp_init_data[9*9*9*9] = {{
{array_data}
        }};

        struct PpDataInit {{
            PpDataInit() {{
                std::memcpy(ppwp2j_mod::pp.data, pp_init_data, sizeof(pp_init_data));
            }}
        }};
        static PpDataInit pp_data_init_;
    }}
}}

extern "C" {{
    int* ppwp2j_mod_pp() {{
        return ppwp2j_mod::pp.data;
    }}
}}
"""

with open('software/mcfm/src/Mods/ppwp2j_mod.hpp', 'w') as f:
    f.write(header_content)

with open('software/mcfm/src/Mods/ppwp2j_mod.cpp', 'w') as f:
    f.write(cpp_content)

print("Files written successfully")
print(f"Header size: {len(header_content)} bytes")
print(f"CPP size: {len(cpp_content)} bytes")
EOF

